-- V50__seed_indian_food_nutrition.sql
-- Seeds 1,014 authentic Indian food items from Indian_Food_Nutrition_Processed.csv.
-- All nutritional values are PER 100g serving.
-- Columns: calories(kcal), carbohydrates(g), protein(g), fat(g),
--          sugar(g), fiber(g), sodium(mg), calcium(mg), iron(mg), vitamin_c(mg)
-- Idempotent: skips rows where description already exists (case-insensitive).

INSERT INTO food (
    id, description, category, calories, carbohydrates, protein, fat,
    sugar, fiber, sodium, calcium, iron, vitamin_c,
    high_sodium, high_fiber, vegan_options, gluten_free,
    keto_friendly, high_cholesterol, low_cholesterol, low_sodium,
    is_recipe, created_at, updated_at
)
SELECT
    v.id::uuid,
    v.description,
    v.category,
    v.calories::double precision,
    v.carbohydrates::double precision,
    v.protein::double precision,
    v.fat::double precision,
    v.sugar::double precision,
    v.fiber::double precision,
    v.sodium::double precision,
    v.calcium::double precision,
    v.iron::double precision,
    v.vitamin_c::double precision,
    v.high_sodium::boolean,
    v.high_fiber::boolean,
    v.vegan_options::boolean,
    v.gluten_free::boolean,
    v.keto_friendly::boolean,
    v.high_cholesterol::boolean,
    v.low_cholesterol::boolean,
    v.low_sodium::boolean,
    v.is_recipe::boolean,
    NOW(),
